// packages/core/test/review-tmp/primers-robustness-final.test.ts
import { expect, it } from 'vitest';
import { designPrimer } from '../../src/primers/design';

function mulberry32(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

it('"unlimited" maxLength on a 10 kb plasmid finishes in < 1 s', { timeout: 120_000 }, () => {
  const random = mulberry32(1);
  let template = '';
  for (let i = 0; i < 10_000; i++) template += 'ACGT'[Math.floor(random() * 4)];
  const t0 = performance.now();
  designPrimer(template, 'circular', { position: 10, direction: 1, maxLength: Number.MAX_SAFE_INTEGER });
  expect(performance.now() - t0).toBeLessThan(1000); // FAILS: 3083 ms
});

// packages/core/test/review-tmp/primers-robustness-final.test.ts
import { expect, it } from 'vitest';
import { tm, tmRange } from '../../src/primers/tm';

it('min/max lie within 0.5 °C of the true extremes over all 65 536 expansions', () => {
  const r = tmRange('ACGTNNNNNNNNACGTACGT');
  expect(r.exact).toBe(false);
  let min = Infinity;
  let max = -Infinity;
  for (let x = 0; x < 65536; x++) {
    let mid = '';
    for (let k = 0; k < 8; k++) mid += 'ACGT'[(x >> (2 * k)) & 3];
    const t = tm(`ACGT${mid}ACGTACGT`);
    min = Math.min(min, t);
    max = Math.max(max, t);
  }
  expect(r.min - min).toBeLessThan(0.5); // FAILS: 2.262
  expect(max - r.max).toBeLessThan(0.5); // (1.49 measured)
});

