// packages/core/test/review-tmp/primers-robustness-findings.test.ts
import { expect, it } from 'vitest';
import type { Primer } from '../../src/types';
import { findBindingSites } from '../../src/primers/binding';
import { tm } from '../../src/primers/tm';

it('allowing a mismatch must not turn a perfect site of an EcoRI-tailed primer into a mismatched one', () => {
  const anneal = 'ATGGCTAGCAAAGGAGAAGAAC'; // 22 nt, perfect match
  const primer: Primer = { id: 'p', name: 'EcoRI-fwd', sequence: 'GCGCGAATTC' + anneal };
  // template base 5' of the site (A) mismatches the tail's last base (C); the next two tail bases (T, T) happen to match
  const template = 'CCCCCCCCCCCCCCCCCCCCGTTA' + anneal + 'TTTTTCACTGGAGTTGTCCC';
  const strict = findBindingSites(template, 'linear', primer);
  const tolerant = findBindingSites(template, 'linear', primer, { maxMismatches: 1 });
  expect(strict).toEqual([expect.objectContaining({ range: { start: 24, end: 46 }, annealedLength: 22, mismatches: 0, tailLength: 10 })]);
  expect(tm(anneal)).toBeCloseTo(58.38, 2);
  expect(tolerant).toEqual(strict); // FAILS
});
// Frequency: 4000 random 200-nt templates, primer = random 10-nt tail (last base forced to mismatch) + the 20-nt template segment ending at 110,
// findBindingSites(..., { maxMismatches: 1 }): 259/4000 perfect sites are reported with mismatches, Tm up to +12.53 °C
// (maxMismatches 2: 256/4000, up to +14.33 °C).

import { expect, it } from 'vitest';
import type { Primer } from '../../src/types';
import { findAllBindingSites, findBindingSites } from '../../src/primers/binding';

function mulberry32(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

it('one over-degenerate primer discards every other primer\'s sites (60 kb template, default options)', () => {
  const random = mulberry32(7);
  let template = '';
  for (let i = 0; i < 60_000; i++) template += 'ACGT'[Math.floor(random() * 4)];
  const good: Primer = { id: 'good', name: 'good', sequence: template.slice(30_000, 30_022) };
  const degenerate: Primer = { id: 'deg', name: 'random-20', sequence: 'N'.repeat(20) };
  expect(findBindingSites(template, 'linear', good)).toHaveLength(1);
  let sites: unknown[] | undefined;
  let error: unknown;
  try { sites = findAllBindingSites(template, 'linear', [good, degenerate]); } catch (e) { error = e; }
  expect(error).toBeUndefined(); // FAILS: RangeError
  expect(sites).toContainEqual(expect.objectContaining({ primerId: 'good' }));
});

