// packages/core/test/review-tmp/primers-science-perf4.test.ts (run: npx vitest run test/review-tmp/primers-science-perf4.test.ts)
import { existsSync, readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { findBindingSites } from '../../src/primers/binding';

const ecoliPath = new URL('../fixtures/large/ecoli_U00096.3.gb', import.meta.url);
describe.skipIf(!existsSync(ecoliPath))('1 primer on the 4.6 Mb genome < 1 s (degenerate 3′ anchor)', () => {
  const text = existsSync(ecoliPath) ? readFileSync(ecoliPath, 'utf8') : '';
  const o = text.indexOf('\nORIGIN');
  const genome = text.slice(o + 7, text.indexOf('\n//', o)).replace(/[^A-Za-z]/g, '').toUpperCase();

  it('SISPA primer FR26RV-N (tag + N9), maxMismatches 1', { timeout: 60_000 }, () => {
    const p = { id: 'FR26RV-N', name: 'FR26RV-N', sequence: 'GTTTCCCAGTCACGATANNNNNNNNN' };
    findBindingSites(genome, 'circular', p); // warm-up (default options: ~45 ms)
    const t0 = performance.now();
    findBindingSites(genome, 'circular', p, { maxMismatches: 1 });
    expect(performance.now() - t0).toBeLessThan(1000);
  });

  it('primer ending in NNNNN, maxMismatches 1, computeTm false (few sites, pure scan cost)', { timeout: 60_000 }, () => {
    const p = { id: 'n5', name: 'n5', sequence: 'ACGATCGGATCCTTAGNNNNN' };
    findBindingSites(genome, 'circular', p);
    const t0 = performance.now();
    const sites = findBindingSites(genome, 'circular', p, { maxMismatches: 1, computeTm: false });
    const elapsed = performance.now() - t0;
    expect(sites.length).toBeLessThan(100);
    expect(elapsed).toBeLessThan(1000);
  });
});

